-- Dayjoy product price-list import, derived from India-BV-Price-May-2026.pdf
-- Prices effective 5 May 2026; INR; amounts shown as inclusive of tax.
CREATE TABLE IF NOT EXISTS dayjoy_products (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_product_no INTEGER UNIQUE,
  product_name TEXT NOT NULL,
  category TEXT NOT NULL,
  mrp_inr NUMERIC(12,2) NOT NULL,
  dp_inr NUMERIC(12,2) NOT NULL,
  bv INTEGER,
  pv INTEGER,
  pack_size TEXT,
  product_id TEXT,
  sku TEXT,
  ingredients TEXT,
  benefits TEXT,
  usage_instructions TEXT,
  dosage TEXT,
  warnings TEXT,
  certifications TEXT,
  product_image_url TEXT,
  source_file TEXT NOT NULL,
  source_page TEXT,
  effective_date DATE,
  data_status TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

